    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td>Successful completion of a senior secondary school qualification similar to the Higher School Certificate (HSC)</td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>Applicants who do not speak English as a first language must meet the University''s English proficiency requirement</li><li>IELTS overall minimum 6.0</li><li>IELTS section minimum 6.0</li></ul></td></tr></tbody></table>',
